{"question": "Phương pháp điều trị cụ thể đối với nang thân răng là gì?", "claim": "Điều trị nang thân răng bằng phương pháp phẫu thuật mở thông nang thông qua việc tiến hành hàn kín ống tủy toàn bộ các răng liên quan.", "internal_evidence": [{"evidence_id": "I1", "content": "Bản nháp kế hoạch phẫu thuật đề xuất mở thông nang thân răng kết hợp nội nha hàn kín ống tủy toàn bộ các răng lân cận."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Cắt bỏ một phần vỏ nang."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Nếu xương đã bị mất quá 2 mm nhưng vẫn chưa quá ½ chiều dài của Implant cần điều trị phẫu thuật lấy bỏ tổ chức viêm nhiễm xung quanh Implant, làm sạch bề mặt Implant và có thể tiến hành ghép xương để tái tạo tổ chức xương đã mất. Bề mặt Implant có thể được làm sạch bằng các chất hóa học (Gel Metronidazole), các phương pháp cơ học sử dụng bàn chải và bột đánh bóng, sử dụng lazer cũng cho kết quả tốt. Sau khi bề mặt Implant được làm sạch có thể tiến hành ghép xương nhằm khôi phục khối lượng xương đã mất. Nếu không ghép xương thì làm nhẵn bề mặt nhám của Implant đã bị bộc lộ nhằm giảm sự tích tụ mảng bám lên bề mặt Implant."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Nang thân răng là nang trong xương hàm, liên quan tới thân răng của răng ngầm hoặc răng thừa ngầm, nang bao bọc một phần hay toàn bộ thân răng. Lòng nang chứa dịch màu vàng chanh hoặc trắng đục do nhiễm khuẩn."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Trường hợp phẫu thuật mở thông nang, sau một thời gian nang thu hẹp thì có thể tiến hành phẫu thuật thì hai lấy bỏ nang và răng ngầm."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["25. NANG THÂN RĂNG", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Phẫu thuật mở thông nang"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["25. NANG THÂN RĂNG", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["25. NANG THÂN RĂNG", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}]}
