{"question": "Triệu chứng lâm sàng điển hình của ung thư tuyến nước bọt mang tai giai đoạn u to gây ra là gì?", "claim": "Ung thư tuyến nước bọt mang tai ở giai đoạn u to có thể gây biến dạng mặt cho người bệnh.", "internal_evidence": [{"evidence_id": "I1", "content": "Khuyến cáo lâm sàng cho thấy khi khối u tuyến nước bọt mang tai phát triển đạt kích thước lớn, nó sẽ chèn ép các cấu trúc xung quanh, làm thay đổi cấu trúc giải phẫu vùng mặt và gây biến dạng mặt rõ rệt cho người bệnh, đòi hỏi phải có chỉ định phẫu thuật cắt bỏ kịp thời."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Khi u phát triển to có thể có bội nhiễm viêm sưng tấy đỏ ngoài mặt và gây viêm xương và rò ra ngoài da"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ U to gây biến dạng mặt."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Điều trị muộn và sai nguyên tắc có thể gây ra tai biến, di chứng trầm trọng, làm ảnh hưởng đến chức năng, thẩm mỹ."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Đối với tình trạng viêm quanh Implant ở giai đoạn ban đầu có nguyên nhân do cấu trúc phục hình hoặc lực nhai quá tải thì tiên lượng điều trị rất khả quan, tuy nhiên đối với tình trạng viêm quanh Implant ở giai đoạn tiến triển trên bệnh nhân bị bệnh viêm quanh răng hoặc không xác định được nguyên nhân gây bệnh thì kết quả điều trị ít khả quan và bệnh vẫn có nguy cơ tiến triển dẫn đến việc phải tháo bỏ Implant."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["38. U XƯƠNG RĂNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Thực thể"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["54. GÃY XƯƠNG HÀM DƯỚI", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}]}
