{"question": "Kết quả cận lâm sàng nào xác định chẩn đoán xác định ung thư tuyến nước bọt mang tai?", "claim": "Chẩn đoán xác định ung thư tuyến nước bọt mang tai dựa vào kết quả giải phẫu bệnh lý thấy hình ảnh tế bào ung thư biểu mô tuyến.", "internal_evidence": [{"evidence_id": "I1", "content": "Sổ tay thực hành lâm sàng ghi nhận việc chẩn đoán xác định các khối u tuyến nước bọt mang tai bắt buộc phải dựa trên kết quả giải phẫu bệnh lý. Việc phát hiện các hình ảnh tế bào ung thư biểu mô tuyến trên tiêu bản sinh thiết là tiêu chuẩn cốt lõi để đưa ra kết luận chính xác về bệnh lý ác tính này."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Nếu phẫu thuật rộng cắt bỏ toàn bộ khối ung thư sớm thì tiên lượng sẽ tốt hơn. Tùy theo phẫu thuật ở giai đoạn nào của tổn thương ung thư mà thời gian sống của bệnh nhân kéo dài sau 5 năm khác nhau. Theo một số tác giả nước ngoài:"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Thấy hình ảnh tổn thương đặc trưng của u men. Dựa vào hình ảnh mô bệnh học, u men được phân loại thành các thể dưới đây:"}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Giải phẫu bệnh lý: thấy hình ảnh tế bào ung thư biểu mô tuyến."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Phẫu thuật cắt rộng lấy bỏ toàn bộ tổn thương ung thư bao gồm cả tuyến mang tai tới mô lành."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["36. U MEN XƯƠNG HÀM", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Cận lâm sàng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "2.2. Cận lâm sàng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}]}
