{"question": "Giả khớp cắn loại III được định nghĩa như thế nào trong nha khoa?", "claim": "Giả khớp cắn loại III là tình trạng sai khớp cắn mà để đạt được sự lồng múi tối đa thì hàm dưới phải trượt ra phía trước dẫn đến tương quan hai hàm là khớp cắn loại III.", "internal_evidence": [{"evidence_id": "I1", "content": "Giả khớp cắn loại III là tình trạng sai khớp cắn mà để đạt được sự lồng múi tối đa, hàm dưới phải trượt ra phía sau, dẫn đến tương quan hai hàm là khớp cắn loại II thay vì loại III như các chẩn đoán thông thường."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Đối với tình trạng viêm quanh Implant ở giai đoạn ban đầu có nguyên nhân do cấu trúc phục hình hoặc lực nhai quá tải thì tiên lượng điều trị rất khả quan, tuy nhiên đối với tình trạng viêm quanh Implant ở giai đoạn tiến triển trên bệnh nhân bị bệnh viêm quanh răng hoặc không xác định được nguyên nhân gây bệnh thì kết quả điều trị ít khả quan và bệnh vẫn có nguy cơ tiến triển dẫn đến việc phải tháo bỏ Implant."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Là tình trạng sai khớp cắn mà để đạt được sự lồng múi tối đa thì hàm dưới phải trượt ra phía trước dẫn đến tương quan hai hàm là khớp cắn loại III, múi ngoài gần của răng hàm lớn vĩnh viễn thứ nhất hàm trên khớp về phía xa so với rãnh ngoài gần của răng hàm lớn vĩnh viễn thứ nhất hàm dưới."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Trong một số trường hợp phải sử dụng khí cụ. c.Thiết lập lại tương quan răng khớp cắn loại I"}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Khi răng hai hàm đạt lồng múi tối đa: Tương quan loại III ở răng hàm lớn thứ nhất và răng nanh."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["19. GIẢ KHỚP CẮN LOẠI III", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["19. GIẢ KHỚP CẮN LOẠI III", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể.", "b. Loại bỏ thói quen xấu làm trượt hàm dưới ra trước"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["19. GIẢ KHỚP CẮN LOẠI III", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "a. Mẫu hàm thạch cao"]}]}
