{"question": "Trong chẩn đoán giả khớp cắn loại III, độ cắn chìa đảo ngược có giá trị như thế nào?", "claim": "Không đúng rằng độ cắn chìa đảo ngược trong chẩn đoán giả khớp cắn loại III có giá trị mang dấu âm.", "internal_evidence": [{"evidence_id": "I1", "content": "Quá trình mòn răng tự nhiên diễn ra theo thời gian phụ thuộc lớn vào tính chất cơ học của thức ăn và lực nhai tác động lên bề mặt răng."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Gia đình có người thuộc thế hệ gần nhất của bệnh nhân (bố mẹ, anh chị em ruột, con đẻ) trước đó đã được chẩn đoán NF-1."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Là tình trạng sai khớp cắn mà để đạt được sự lồng múi tối đa thì hàm dưới phải trượt ra phía trước dẫn đến tương quan hai hàm là khớp cắn loại III, múi ngoài gần của răng hàm lớn vĩnh viễn thứ nhất hàm trên khớp về phía xa so với rãnh ngoài gần của răng hàm lớn vĩnh viễn thứ nhất hàm dưới."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Trong một số trường hợp phải sử dụng khí cụ. c.Thiết lập lại tương quan răng khớp cắn loại I"}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Độ cắn chìa đảo ngược: có giá trị âm."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["41. U XƠ THẦN KINH", "III. CHẨN ĐOÁN", "1. Lâm sàng", "a. Tiêu chuẩn chẩn đoán NF-1"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["19. GIẢ KHỚP CẮN LOẠI III", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["19. GIẢ KHỚP CẮN LOẠI III", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể.", "b. Loại bỏ thói quen xấu làm trượt hàm dưới ra trước"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["19. GIẢ KHỚP CẮN LOẠI III", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "b. Trong miệng"]}]}
