{"question": "Triệu chứng lâm sàng và dấu hiệu nhận biết của áp xe tuyến dưới lưỡi là gì?", "claim": "Áp xe tuyến dưới lưỡi có đặc điểm là dấu hiệu ngoài miệng ít, sàn miệng bên bệnh sưng cứng và tình trạng khít hàm ít.", "internal_evidence": [{"evidence_id": "I1", "content": "- Biểu hiện lâm sàng của áp xe tuyến dưới lưỡi gồm dấu hiệu ngoài miệng xuất hiện ít.\n- Vùng sàn miệng ở bên tổn thương có hiện tượng sưng cứng rõ rệt.\n- Triệu chứng khít hàm đi kèm thường xuất hiện ở mức độ ít."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Có khối u ở vùng lưỡi, má, trên mặt, vùng dưới hàm, bên cổ với các đặc điểm sau:"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Áp xe tuyến dưới lưỡi: dấu hiệu ngoài miệng ít, sàn miệng bên bệnh sưng cứng, khít hàm ít."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Vùng dưới hàm có 1 khối sưng lớn, da trên khối sưng nóng đỏ hoặc tím, căng, nề, có thể thâm nhiễm lan rộng lên trên phần thấp của má,phía trước lan đến vùng dưới cằm,phía sau lan đến vùng cổ bên,phía dưới lan xuống xương móng.Lồi bờ nền xương hàm dưới bị xóa."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Hàm dưới có thể đổi hướng ra trước hoặc sang bên khi gặp điểm chạm sớm,"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["40. U BẠCH MẠCH"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["31. ÁP XE VÙNG DƯỚI HÀM", "III. CHẨN ĐOÁN", "2 Chẩn đoán phân biệt"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["31. ÁP XE VÙNG DƯỚI HÀM", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["19. GIẢ KHỚP CẮN LOẠI III", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "b. Trong miệng"]}]}
