{"question": "Chỉ định cận lâm sàng nào được thực hiện để đánh giá tổn thương răng nguyên nhân trong trường hợp áp xe má?", "claim": "X quang thường quy có biểu hiện tổn thương răng nguyên nhân là phương pháp cận lâm sàng được chỉ định để chẩn đoán xác định áp xe má.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong thực hành chẩn đoán áp xe má, việc chỉ định chụp X quang thường quy đóng vai trò quan trọng nhằm bộc lộ rõ các tổn thương tại răng nguyên nhân đang gây ra ổ nhiễm trùng vùng hàm mặt."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Có biểu hiện bệnh lý ở răng nguyên nhân.Thử tủy thường dương tính."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Không xác định được nguyên nhân, thực chất là mộ t dị dạng bẩm sinh mạch"}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- X quang thường quy Có biểu hiện tổn thương răng nguyên nhân."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Gãy xương hàm dưới luôn có các triệu chứng lâm sàng và X quang rõ rệt nên không cần chẩn đoán phân biệt."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["38. U XƯƠNG RĂNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Thực thể"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["40. U BẠCH MẠCH"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["30. ÁP XE MÁ", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Cận lâm sàng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["54. GÃY XƯƠNG HÀM DƯỚI", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}]}
