{"question": "Bệnh nhân mắc u xơ thần kinh bẩm sinh cần lưu ý điều gì về phòng bệnh?", "claim": "Đối với các trường hợp u xơ thần kinh bẩm sinh, quy định hướng dẫn tư vấn trước và sau sinh là rất cần thiết.", "internal_evidence": [{"evidence_id": "I1", "content": "Đối với các bệnh lý di truyền như u xơ thần kinh bẩm sinh, việc thực hiện tư vấn y tế chuyên sâu cho sản phụ trước và sau khi sinh đóng vai trò quan trọng trong công tác quản lý và phòng ngừa."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Trường hợp u bị bội nhiễm: có cảm giác đau, niêm mạc và da trên u đỏ, các răng trên u lung lay nhiều. Bệnh nhân có sốt và xuất hiện hạch vùng ngoại vi."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Đối với tình trạng viêm quanh Implant ở giai đoạn ban đầu có nguyên nhân do cấu trúc phục hình hoặc lực nhai quá tải thì tiên lượng điều trị rất khả quan, tuy nhiên đối với tình trạng viêm quanh Implant ở giai đoạn tiến triển trên bệnh nhân bị bệnh viêm quanh răng hoặc không xác định được nguyên nhân gây bệnh thì kết quả điều trị ít khả quan và bệnh vẫn có nguy cơ tiến triển dẫn đến việc phải tháo bỏ Implant."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Tư vấn trước và sau sinh với những u bẩm sinh."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Tùy theo mức độ mất xương xung quanh Implant mà có thể có các mức độ xử trí khác nhau. Nếu xương chưa bị mất quá 2 mm thì việc điều trị có thể giới hạn ở mức độ lấy cao răng, mảng bám và kiểm soát mảng bám kết hợp làm sạch Abutment, chỉnh sửa cấu trúc phục hình nếu cần và hướng dẫn bệnh nhân tăng cường vệ sinh răng miệng."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["36. U MEN XƯƠNG HÀM", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Giai đoạn u to làm phồng xương hàm"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["41. U XƠ THẦN KINH", "VI. PHÒNG BỆNH"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}]}
