{"question": "Triệu chứng lâm sàng nào thường xuất hiện ở vùng môi dưới và cằm khi bệnh nhân bị gãy xương hàm dưới?", "claim": "Triệu chứng dị cảm thường biểu hiện bằng tình trạng tê môi dưới và vùng da cằm ở bệnh nhân gãy xương hàm dưới.", "internal_evidence": [{"evidence_id": "I1", "content": "Bệnh nhân gãy xương hàm dưới thường có triệu chứng dị cảm, biểu hiện rõ rệt qua việc tê ở môi dưới và vùng da cằm."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Gãy xương hàm dưới luôn có các triệu chứng lâm sàng và X quang rõ rệt nên không cần chẩn đoán phân biệt."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Dị cảm: thường biểu hiện tê môi dưới, da vùng cằm."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Đối với tình trạng viêm quanh Implant ở giai đoạn ban đầu có nguyên nhân do cấu trúc phục hình hoặc lực nhai quá tải thì tiên lượng điều trị rất khả quan, tuy nhiên đối với tình trạng viêm quanh Implant ở giai đoạn tiến triển trên bệnh nhân bị bệnh viêm quanh răng hoặc không xác định được nguyên nhân gây bệnh thì kết quả điều trị ít khả quan và bệnh vẫn có nguy cơ tiến triển dẫn đến việc phải tháo bỏ Implant."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Trong trường hợp nang thân răng ở xương hàm dưới có thể gây tê môi dưới do nang to chèn vào ống răng dưới."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["54. GÃY XƯƠNG HÀM DƯỚI", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["54. GÃY XƯƠNG HÀM DƯỚI", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Triệu chứng lâm sàng gãy xương hàm dưới"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["25. NANG THÂN RĂNG", "II. NGUYÊN NHÂN", "1. Chẩn đoán xác định", "1.1 Lâm sàng"]}]}
