{"question": "U bạch mạch vùng hàm mặt có phải do nhiễm trùng răng không?", "claim": "U bạch mạch vùng hàm mặt là dạng dị tật bẩm sinh và hoàn toàn không xuất phát từ các ổ nhiễm trùng cấp tính.", "internal_evidence": [{"evidence_id": "I1", "content": "Khuyến cáo lâm sàng ghi nhận u bạch mạch vùng hàm mặt là dạng dị tật bẩm sinh của hệ thống mạch máu và bạch huyết, hoàn toàn không xuất phát từ các ổ nhiễm trùng cấp tính vùng răng hàm mặt."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Nếu không được điều trị thì u gây phá hủy xương hàm nhanh chóng, có thể gây gãy xương bệnh lý và xâm lấn mô mềm xung quanh. U men còn có nguy cơ chuyển dạng ác tính."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- X quang Có hình ảnh tổn thương phá hủy xương hàm dạng nang có thể một hoặc nhiều buồng, ranh giới không rõ. Có thể có hình ảnh tiêu chân răng các răng liên quan."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Hàm dưới có thể đưa về được tương quan bình thường nhưng do thói quen đưa ra trước tạo ra tương quan răng hàm lớn thứ nhất loại III. 1.2.Cận lâm sàng"}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Không xác định được nguyên nhân, thực chất là mộ t dị dạng bẩm sinh mạch"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["36. U MEN XƯƠNG HÀM", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["36. U MEN XƯƠNG HÀM", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Cận lâm sàng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["19. GIẢ KHỚP CẮN LOẠI III", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "b. Trong miệng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["40. U BẠCH MẠCH"]}], "conversation": [{"role": "user", "content": "U bạch mạch vùng hàm mặt có phải do nhiễm trùng răng không?"}, {"role": "assistant", "content": "Chắc là do các ổ nhiễm trùng răng hàm mặt lan rộng gây ra đấy."}]}
