{"question": "Dấu hiệu lâm sàng đặc trưng nào giúp phân biệt áp xe tuyến dưới hàm khi thăm khám?", "claim": "Áp xe tuyến dưới hàm không có biểu hiện chảy mủ qua lỗ ống Wharton khi thăm khám.", "internal_evidence": [{"evidence_id": "I1", "content": "- Thăm khám lâm sàng vùng sàn miệng và tuyến nước bọt phụ giúp đánh giá tình trạng viêm nhiễm vùng hàm mặt.\n- Việc phát hiện các dấu hiệu tắc nghẽn ống tiết đòi hỏi kết hợp chẩn đoán hình ảnh để xác định chính xác vị trí tổn thương."}, {"evidence_id": "I2", "content": "Chỉ định thăm khám lâm sàng và đánh giá cấu trúc ống Wharton cần tuân thủ các bước kiểm tra tuyến nước bọt mang tính hệ thống. Việc ghi nhận chính xác dòng chảy dịch tiết giúp loại trừ các bệnh lý tắc nghẽn cấp tính."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Viêm hạch mủ dưới hàm: bắt đầu dưới dạng nổi cục sưng đau, sau lan ra cả vùng, không có dấu hiệu khít hàm."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Trong miệng U làm phồng xương hàm, làm đầy ngách lợi, thời kỳ đầu niêm mạc và răng trên u bình thường, ấn cứng. Khi u đã phá hủy tới vỏ xương thì ấn có dấu hiệu bóng nhựa. Khi u đã phá hủy hầu hết xương có các dấu hiệu dưới đây:"}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Áp xe tuyến dưới hàm: dấu hiệu chảy mủ qua lỗ ống Wharton khi thăm khám."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Hàm dưới có thể đưa về được tương quan bình thường nhưng do thói quen đưa ra trước tạo ra tương quan răng hàm lớn thứ nhất loại III. 1.2.Cận lâm sàng"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["31. ÁP XE VÙNG DƯỚI HÀM", "III. CHẨN ĐOÁN", "2 Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["36. U MEN XƯƠNG HÀM", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Giai đoạn u to làm phồng xương hàm"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["31. ÁP XE VÙNG DƯỚI HÀM", "III. CHẨN ĐOÁN", "2 Chẩn đoán phân biệt"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["19. GIẢ KHỚP CẮN LOẠI III", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "b. Trong miệng"]}]}
