{"question": "Cách xử trí và tiên lượng trong bệnh lý áp xe má như thế nào?", "claim": "Tiên lượng điều trị áp xe má sẽ rất tốt nếu thực hiện dẫn lưu mủ kết hợp với việc điều trị triệt để răng nguyên nhân.", "internal_evidence": [{"evidence_id": "I1", "content": "Sổ tay thực hành lâm sàng ghi nhận đối với các ca bệnh áp xe má, phác đồ điều trị tiêu chuẩn đòi hỏi phải tiến hành thủ thuật dẫn lưu mủ triệt để kết hợp với việc loại bỏ hoàn toàn ổ nhiễm trùng bắt nguồn từ răng nguyên nhân để đạt kết quả phục hồi tốt nhất."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Nếu phẫu thuật triệt để lấy bỏ toàn bộ u thì sẽ có tiên lượng tốt."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Nếu xương đã bị mất quá 2 mm nhưng vẫn chưa quá ½ chiều dài của Implant cần điều trị phẫu thuật lấy bỏ tổ chức viêm nhiễm xung quanh Implant, làm sạch bề mặt Implant và có thể tiến hành ghép xương để tái tạo tổ chức xương đã mất. Bề mặt Implant có thể được làm sạch bằng các chất hóa học (Gel Metronidazole), các phương pháp cơ học sử dụng bàn chải và bột đánh bóng, sử dụng lazer cũng cho kết quả tốt. Sau khi bề mặt Implant được làm sạch có thể tiến hành ghép xương nhằm khôi phục khối lượng xương đã mất. Nếu không ghép xương thì làm nhẵn bề mặt nhám của Implant đã bị bộc lộ nhằm giảm sự tích tụ mảng bám lên bề mặt Implant."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Nếu dẫn lưu mủ phối hợp với điều trị răng nguyên nhân thì có kết quả điều trị tốt."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Khám chuyên khoa răng hàm mặt để phát hiện các tổn thương sớm và điều trị kịp thời."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["36. U MEN XƯƠNG HÀM", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["30. ÁP XE MÁ", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "VI. PHÒNG BỆNH"]}]}
