{"question": "Cách xử trí trật khớp hàm dưới hai bên khi nắn chỉnh không thành công gây co thắt cơ nghiêm trọng là gì?", "claim": "Những nỗ lực nắn chỉnh trật khớp hàm dưới lặp đi lặp lại không thành công có thể dẫn đến co thắt cơ nghiêm trọng, khi đó bắt buộc phải dùng thuốc an thần trong quá trình phẫu thuật hoặc thuốc gây liệt để kiểm soát đường thở nâng cao.", "internal_evidence": [{"evidence_id": "I1", "content": "Khuyến cáo điều trị cho thấy những nỗ lực nắn chỉnh trật khớp hàm dưới lặp đi lặp lại nhưng không thành công có nguy cơ dẫn đến tình trạng co thắt cơ nghiêm trọng. Khi đó, quy trình xử trí bắt buộc phải chuyển sang sử dụng thuốc an thần trong phòng mổ hoặc kết hợp thuốc gây liệt nhằm kiểm soát hiệu quả đường thở nâng cao cho người bệnh."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "hai bên để nắn chỉnh lồi cầu (tức là đẩy xương hàm trở lại vị trí bình thường). Điểm mấu chốt là áp lực đầu tiên xuống phía dưới hàm, sau đó từ từ hướng dẫn toàn bộ phần sau hàm dưới: Sau đó trở lại. \"Thường thì hàm dưới sẽ khớp vào vị trí của khớp."}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "Những nỗ lực không thành công lặp đi lặp lại có thể dẫn đến co thắt cơ nghiêm trọng, tình trạng này bắt buộc phải dùng thuốc an thần trong quá trình phẫu thuật (ví dụ: propofol) hoặc thậm chí là thuốc gây liệt trong khoa hồi sức tích cực hoặc phòng phẫu thuật để kiểm soát đường thở nâng cao nhằm mục đích nắn chỉnh khớp thành công."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Khớp được hình thành bởi lồi cầu xương hàm dưới và ổ khớp của xương thái dương."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "Trật khớp TMJ ra trước xảy ra khi lồi cầu di chuyển ra phía trước và tiến về phía trước khớp."}, {"quote_id": "P2.Q3", "evidence_id": "P2", "text": "Trật khớp TMJ làm giãn các dây chằng của các dây chằng, ống động mạch trong và ngoài cùng, cơ thái dương, gây ra co thắt đau (trismus). Trismus ngăn không cho lồi cầu trở lại xương hàm dưới, ngăn chặn sự đóng kín của miệng."}, {"quote_id": "P2.Q4", "evidence_id": "P2", "text": "Khi lồi cầu được phục hồi vào xương hàm, hàm sẽ bị đóng lại dưới tác động của lực cơ, khiến cả lưỡi của bệnh nhân và ngón tay của người phẫu thuật có nguy cơ bị cắn."}, {"quote_id": "P2.Q5", "evidence_id": "P2", "text": "Trật khớp TMJ tự phát thường nhiều hơn hai bên so với một bên."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Nhiễm trùng trong đường dẫn kim: Sử dụng phương pháp phong bế dây thần kinh hoặc các biện pháp gây mê khác."}, {"quote_id": "P3.Q2", "evidence_id": "P3", "text": "Rối loạn đông máu*: Khi khả thi, điều trị trước khi làm thủ thuật."}, {"quote_id": "P3.Q3", "evidence_id": "P3", "text": "Mang thai: Trong khi nhiều hướng dẫn nêu rằng bệnh nhân có thể được điều trị an toàn trong suốt thai kỳ, thì việc điều trị thực sự theo lựa chọn lý tưởng nhất là nên hoãn lại trong ba tháng đầu tiên của thai kỳ để ngăn ngừa nguy cơ gây hại cho sự phát triển của trẻ (1)."}], "public_sources": [{"evidence_id": "P1", "title": "Cách nắn chỉnh trật khớp hàm dưới", "heading_path": ["Mô tả từng bước nắn chỉnh trật khớp hàm dưới"]}, {"evidence_id": "P2", "title": "Cách nắn chỉnh trật khớp hàm dưới", "heading_path": ["Giải phẫu liên quan trong nắn chỉnh trật khớp hàm dưới"]}, {"evidence_id": "P3", "title": "Cách thực hiện gây tê thấm trên màng xương", "heading_path": ["Chống chỉ định gây tê thấm trên màng xương"]}]}
