{"question": "Biểu hiện ngoài mặt của bệnh u tuyến nước bọt vòm miệng là gì?", "claim": "Biểu hiện ở ngoài mặt của bệnh u tuyến nước bọt vòm miệng là hoàn toàn không có biểu hiện gì đặc biệt.", "internal_evidence": [{"evidence_id": "I1", "content": "- Khám thực thể vùng ngoài mặt ở bệnh nhân u tuyến nước bọt vòm miệng thường không ghi nhận các triệu chứng bất thường.\n- Các biểu hiện lâm sàng hầu như không xuất hiện rõ ra bên ngoài ở giai đoạn đầu của khối u."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Ung thư tuyến nước bọt mang tai là một ung thư biểu mô của tuyến, nang tuyến hoặc u hỗn hợp tuyến mang tai thoái hóa ác tính. II NGUYÊN NHÂN"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Răng nguyên nhân: có biểu hiện bệnh lý của răng nguyên nhân."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Răng nguyên nhân: có biểu hiện bệnh lý của răng nguyên nhân."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Ngoài mặt: Không có biểu hiện."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["31. ÁP XE VÙNG DƯỚI HÀM", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["30. ÁP XE MÁ", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["47. U TUYẾ N NƯỚ C BỌ T VÒ M MIỆ NG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}]}
