{"question": "Kết quả chẩn đoán hình ảnh CT Scanner của bệnh nhân áp xe vùng dưới hàm thường hiển thị hình ảnh gì?", "claim": "Trên phim chụp CT Scanner của bệnh nhân áp xe vùng dưới hàm thường có hình ảnh khối thấu quang với ranh giới rõ ràng ở vùng dưới hàm.", "internal_evidence": [{"evidence_id": "I1", "content": "Phim cắt lớp vi tính (CT Scanner) ghi nhận có sự xuất hiện của khối thấu quang có ranh giới rõ nằm tại khu vực vùng dưới hàm."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Là áp xe khu trú ở vùng dưới hàm, nguyên nhân thường do răng."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Có khối u ở vùng lưỡi, má, trên mặt, vùng dưới hàm, bên cổ với các đặc điểm sau:"}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- X quang thường quy Thường là một khối cản tương đối đồng nhất, hình tròn liền với 1 hay nhiều chân răng, xung quanh vùng cản quang là vùng sang mỏng, bờ rõ ràng."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- CT Scanner: có khối thấu quang ranh giới rõ ở vùng dưới hàm."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["31. ÁP XE VÙNG DƯỚI HÀM", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["40. U BẠCH MẠCH"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["38. U XƯƠNG RĂNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Cận lâm sàng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["31. ÁP XE VÙNG DƯỚI HÀM", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Cận lâm sàng"]}]}
