{"question": "Đèn Wood được sử dụng trong cận lâm sàng u xơ thần kinh nhằm phát hiện tổn thương da nào?", "claim": "Trong cận lâm sàng u xơ thần kinh, việc sử dụng đèn Wood giúp phát hiện các dát cà-phê sữa không điển hình.", "internal_evidence": [{"evidence_id": "I1", "content": "Phương pháp chiếu đèn đèn Wood trong thăm khám cận lâm sàng là công cụ hỗ trợ đắc lực giúp bác sĩ phát hiện chính xác các tổn thương dát cà-phê sữa không điển hình xuất hiện trên da của người bệnh u xơ thần kinh."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "U xơ thần kinh là bệnh di truyền trội trên nhiễm sắc thể, ảnh hưởng đến thần kinh, da và xương."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Đèn Wood: phát hiện các dát cà-phê sữa không điển hình."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- U xương hàm trên: ranh giới không rõ, mật độ chắc, tổn thương xuất phát từ xương trước."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Nếu điều trị phẫu thuật lấy bỏ được toàn bộ u thì kết quả tốt. Nếu u to, phẫu thuật không triệt để, thì u tiếp tục phát triển."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["41. U XƠ THẦN KINH", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["41. U XƠ THẦN KINH", "III. CHẨN ĐOÁN", "2. Cận lâm sàng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["47. U TUYẾ N NƯỚ C BỌ T VÒ M MIỆ NG", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["40. U BẠCH MẠCH", "2. Chẩn đoán phân biệt"]}]}
