{"question": "U bạch mạch ở vùng hàm mặt thường xuất hiện tại những vị trí giải phẫu nào?", "claim": "U bạch mạch có thể xuất hiện dưới dạng khối u ở vùng lưỡi, má, trên mặt, vùng dưới hàm, bên cổ.", "internal_evidence": [{"evidence_id": "I1", "content": "U bạch mạch vùng hàm mặt thường biểu hiện lâm sàng dưới dạng các khối u mềm, kích thước thay đổi. Các vị trí giải phẫu xuất hiện phổ biến nhất bao gồm vùng lưỡi, niêm mạc má, bề mặt trên của mặt, vùng dưới hàm và dọc theo bên cổ."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Hiếm gặp u men ở hàm trên. Nếu gặp thì có thể có thấy triệu chứng mũi xoang."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Trường hợp u bị bội nhiễm: có cảm giác đau, niêm mạc và da trên u đỏ, các răng trên u lung lay nhiều. Bệnh nhân có sốt và xuất hiện hạch vùng ngoại vi."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Sưng nề và tụ máu: Tùy theo vị trí, mức độ chấn thương mà dấu hiệu sưng nề và tụ máu có những mức độ nhiều ít khác nhau, có thể gặp ở ngoài hoặc trong miệng."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Có khối u ở vùng lưỡi, má, trên mặt, vùng dưới hàm, bên cổ với các đặc điểm sau:"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["36. U MEN XƯƠNG HÀM", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Giai đoạn u to làm phồng xương hàm"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["36. U MEN XƯƠNG HÀM", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Giai đoạn u to làm phồng xương hàm"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["54. GÃY XƯƠNG HÀM DƯỚI", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Triệu chứng lâm sàng gãy xương hàm dưới"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["40. U BẠCH MẠCH"]}]}
