{"question": "Biểu hiện lâm sàng đặc trưng của khớp cắn ngược do răng là gì?", "claim": "Khớp cắn ngược do răng chỉ có biểu hiện khớp cắn ngược ở vùng răng cửa.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong các trường hợp sai khớp cắn ngược do nguyên nhân từ răng, nhóm bệnh nhân này thường chỉ có biểu hiện lệch lạc khớp cắn giới hạn ở khu vực răng cửa thay vì ảnh hưởng đến toàn bộ cấu trúc xương hàm hai bên."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Chỉ có biểu hiện khớp cắn ngược vùng răng cửa"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Khám định kỳ để phát hiện tổn thương sớm và điều trị kịp thời, nhất là ở các trường hợp nguy cơ cao như bệnh nhân có tiền sử viêm quanh răng, bệnh nhân mắc bệnh tiểu đường, hút thuốc lá, điều trị corticoid kéo dài,…."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Là tình trạng sai khớp cắn mà để đạt được sự lồng múi tối đa thì hàm dưới phải trượt ra phía trước dẫn đến tương quan hai hàm là khớp cắn loại III, múi ngoài gần của răng hàm lớn vĩnh viễn thứ nhất hàm trên khớp về phía xa so với rãnh ngoài gần của răng hàm lớn vĩnh viễn thứ nhất hàm dưới."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Thương tổn đặc trưng ở xương: loạn sản xương bướm hay mỏng màng xương dài có hoặc không kèm khớp giả."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["19. GIẢ KHỚP CẮN LOẠI III", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt", "b. Khớp cắn ngược do răng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "VI. PHÒNG BỆNH"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["19. GIẢ KHỚP CẮN LOẠI III", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["41. U XƠ THẦN KINH", "III. CHẨN ĐOÁN", "1. Lâm sàng", "a. Tiêu chuẩn chẩn đoán NF-1"]}]}
