{"question": "Phương pháp phẫu thuật nào được chỉ định để điều trị gãy xương hàm dưới trong tài liệu hướng dẫn?", "claim": "Điều trị phẫu thuật gãy xương hàm dưới được thực hiện bằng phương pháp kết hợp xương bằng chỉ thép.", "internal_evidence": [{"evidence_id": "I1", "content": "Phác đồ điều trị ngoại khoa cho gãy xương hàm dưới ghi nhận phương pháp kết hợp xương bằng chỉ thép."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Khám định kỳ để phát hiện tổn thương sớm và điều trị kịp thời, nhất là ở các trường hợp nguy cơ cao như bệnh nhân có tiền sử viêm quanh răng, bệnh nhân mắc bệnh tiểu đường, hút thuốc lá, điều trị corticoid kéo dài,…."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Nếu điều trị phẫu thuật lấy bỏ được toàn bộ u thì kết quả tốt."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Tùy theo mức độ mất xương xung quanh Implant mà có thể có các mức độ xử trí khác nhau. Nếu xương chưa bị mất quá 2 mm thì việc điều trị có thể giới hạn ở mức độ lấy cao răng, mảng bám và kiểm soát mảng bám kết hợp làm sạch Abutment, chỉnh sửa cấu trúc phục hình nếu cần và hướng dẫn bệnh nhân tăng cường vệ sinh răng miệng."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Kết hợp xương bằng chỉ thép"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "VI. PHÒNG BỆNH"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["38. U XƯƠNG RĂNG", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["54. GÃY XƯƠNG HÀM DƯỚI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Điều trị bằng phẫu thuật."]}]}
