{"question": "Chẩn đoán xác định ung thư tuyến nước bọt mang tai dựa vào những yếu tố nào?", "claim": "Việc chẩn đoán xác định ung thư tuyến nước bọt mang tai được căn cứ dựa vào các triệu chứng lâm sàng, kết quả X quang và giải phẫu bệnh lý.", "internal_evidence": [{"evidence_id": "I1", "content": "Quá trình chẩn đoán xác định ung thư tuyến nước bọt mang tai đòi hỏi sự kết hợp toàn diện giữa việc khai thác triệu chứng lâm sàng, đánh giá các hình ảnh tổn thương trên phim X-quang và kết quả phân tích giải phẫu bệnh lý chi tiết từ mô sinh thiết."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Phẫu thuật cắt rộng lấy bỏ toàn bộ tổn thương ung thư bao gồm cả tuyến mang tai tới mô lành."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Đối với tình trạng viêm quanh Implant ở giai đoạn ban đầu có nguyên nhân do cấu trúc phục hình hoặc lực nhai quá tải thì tiên lượng điều trị rất khả quan, tuy nhiên đối với tình trạng viêm quanh Implant ở giai đoạn tiến triển trên bệnh nhân bị bệnh viêm quanh răng hoặc không xác định được nguyên nhân gây bệnh thì kết quả điều trị ít khả quan và bệnh vẫn có nguy cơ tiến triển dẫn đến việc phải tháo bỏ Implant."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Xạ trị: thường áp dụng xạ trị để hỗ trợ điều trị ung thư tuyến mang tai sau phẫu thuật."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Dựa vào các triệu chứng lâm sàng, X quang và giải phẫu bệnh lý."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định"]}]}
