{"question": "Triệu chứng toàn thân của bệnh nhân bị áp xe má ở giai đoạn chẩn đoán xác định gồm những gì?", "claim": "Bệnh nhân bị áp xe má có biểu hiện nhiễm trùng toàn thân bao gồm sốt cao, mạch nhanh và hơi thở hôi.", "internal_evidence": [{"evidence_id": "I1", "content": "- Bệnh nhân áp xe má có các triệu chứng nhiễm trùng toàn thân đặc trưng bao gồm tình trạng sốt cao, nhịp tim nhanh.\n- Hơi thở của người bệnh có mùi hôi nặng do ổ mủ phát triển trong khoang miệng và vùng lân cận."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Trường hợp u bị bội nhiễm: có cảm giác đau, niêm mạc và da trên u đỏ, các răng trên u lung lay nhiều. Bệnh nhân có sốt và xuất hiện hạch vùng ngoại vi."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Nếu không điều trị u ở giai đoạn sớm, u có thể phát triển xâm lấn xương hàm và thóai hóa ác tính. 2.Biến chứng U chuyển dạng thành ác tính."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Có biểu hiện nhiễm trùng: sốt cao, mạch nhanh, hơi thở hôi…."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Gia đình có người thuộc thế hệ gần nhất của bệnh nhân (bố mẹ, anh chị em ruột, con đẻ) trước đó đã được chẩn đoán NF-1."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["36. U MEN XƯƠNG HÀM", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Giai đoạn u to làm phồng xương hàm"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["47. U TUYẾ N NƯỚ C BỌ T VÒ M MIỆ NG", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["30. ÁP XE MÁ", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "a. Toàn thân"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["41. U XƠ THẦN KINH", "III. CHẨN ĐOÁN", "1. Lâm sàng", "a. Tiêu chuẩn chẩn đoán NF-1"]}]}
