{"question": "Nguyên tắc phẫu thuật điều trị ung thư tuyến nước bọt mang tai bao gồm những phương pháp nào?", "claim": "Điều trị ung thư tuyến nước bọt mang tai áp dụng phương pháp phẫu thuật cắt bỏ rộng tổn thương ung thư phối hợp với nạo vét hạch vùng cổ.", "internal_evidence": [{"evidence_id": "I1", "content": "Nguyên tắc phẫu thuật trong điều trị ung thư tuyến nước bọt mang tai là thực hiện cắt bỏ rộng rãi toàn bộ vùng tổn thương ác tính phối hợp đồng thời với thủ thuật nạo vét hệ thống hạch vùng cổ nhằm ngăn chặn di căn."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Phẫu thuật cắt bỏ rộng tổn thương ung thư phối hợp với nạo vét hạch vùng cổ."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Xạ trị: thường áp dụng xạ trị để hỗ trợ điều trị ung thư tuyến mang tai sau phẫu thuật."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Nếu điều trị đúng, phẫu thuật cắt nang và lấy răng ngầm sẽ có kết quả tốt, không tái phát."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Nếu điều trị phẫu thuật lấy bỏ được toàn bộ u thì kết quả tốt. Nếu u to, phẫu thuật không triệt để, thì u tiếp tục phát triển."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "IV. ĐIỀU TRỊ", "1. Nguyên tắc"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["25. NANG THÂN RĂNG", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["40. U BẠCH MẠCH", "2. Chẩn đoán phân biệt"]}]}
