{"question": "Dấu hiệu lâm sàng chính của bệnh viêm quanh Implant theo quy chuẩn Bộ Y tế là gì?", "claim": "Triệu chứng lâm sàng quan trọng của viêm quanh Implant là tình trạng tăng độ sâu túi xung quanh Implant.", "internal_evidence": [{"evidence_id": "I1", "content": "Khuyến cáo lâm sàng trong việc chẩn đoán và điều trị viêm quanh Implant yêu cầu bác sĩ nha khoa phải tiến hành đo đạc kỹ lưỡng các chỉ số quanh trụ. Triệu chứng lâm sàng quan trọng và phổ biến nhất của bệnh lý này là tình trạng gia tăng đáng kể độ sâu túi quanh Implant."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Tăng độ sâu túi xung quanh Implant."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Viêm quanh Implant chẩn đóan phân biệt với Viêm lợi quanh Implant, và dựa vào các triệu chứng dưới đây:"}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Loại bỏ tác nhân gây bệnh và ổ viêm nhiễm xung quanh Implant."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Đối với tình trạng viêm quanh Implant ở giai đoạn ban đầu có nguyên nhân do cấu trúc phục hình hoặc lực nhai quá tải thì tiên lượng điều trị rất khả quan, tuy nhiên đối với tình trạng viêm quanh Implant ở giai đoạn tiến triển trên bệnh nhân bị bệnh viêm quanh răng hoặc không xác định được nguyên nhân gây bệnh thì kết quả điều trị ít khả quan và bệnh vẫn có nguy cơ tiến triển dẫn đến việc phải tháo bỏ Implant."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "III. CHẨN ĐOÁN", "1.1. Lâm sàng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "IV. ĐIỀU TRỊ", "1. Nguyên tắc"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}]}
