{"question": "Áp xe má điều trị qua đường trong miệng có quy định gì không bác sĩ?", "claim": "Điều trị tại chỗ bằng đường trong miệng đối với áp xe má bắt buộc phải thực hiện điều trị răng nguyên nhân.", "internal_evidence": [{"evidence_id": "I1", "content": "Hướng dẫn thực hành lâm sàng quy định rõ việc điều trị tại chỗ bằng đường trong miệng đối với áp xe má bắt buộc phải thực hiện điều trị răng nguyên nhân."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Tùy theo mức độ mất xương xung quanh Implant mà có thể có các mức độ xử trí khác nhau. Nếu xương chưa bị mất quá 2 mm thì việc điều trị có thể giới hạn ở mức độ lấy cao răng, mảng bám và kiểm soát mảng bám kết hợp làm sạch Abutment, chỉnh sửa cấu trúc phục hình nếu cần và hướng dẫn bệnh nhân tăng cường vệ sinh răng miệng."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Nếu dẫn lưu mủ phối hợp với điều trị răng nguyên nhân thì có kết quả điều trị tốt."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Nếu điều trị đúng, phẫu thuật cắt nang và lấy răng ngầm sẽ có kết quả tốt, không tái phát."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Điều trị răng nguyên nhân."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["30. ÁP XE MÁ", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["25. NANG THÂN RĂNG", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["30. ÁP XE MÁ", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Điều trị tại chỗ", "a. Đường trong miệng"]}], "conversation": [{"role": "user", "content": "Áp xe má điều trị qua đường trong miệng có quy định gì không bác sĩ?"}, {"role": "assistant", "content": "Chỉ cần bơm rửa thông thường là được, không bắt buộc phải tìm răng nguyên nhân."}]}
